22: window.loadHistory = (function() {
23:     // Date of last seen item.
24:     var lastItemDate = null;
25: 
26:     // Each request for new items includes the time of the last item and an
27:     // offset. The offset is equal to the number of items from the previous
28:     // request that had time=nextTime, and causes the next request to skip
29:     // those items to avoid duplicates.
30:     var nextTime = null;
31:     var nextOffset = 0;
32: 
33:     // The URL to fetch data from.
34:     var DATA_URL = "qute://history/data";
35: 
36:     // Various fixed elements
37:     var EOF_MESSAGE = document.getElementById("eof");
38:     var LOAD_LINK = document.getElementById("load");
39:     var HIST_CONTAINER = document.getElementById("hist-container");
40: 
41:     /**
42:      * Finds or creates the session table>tbody to which item with given date
43:      * should be added.
44:      *
45:      * @param {Date} date - the date of the item being added.
46:      * @returns {Element} the element to which new rows should be added.
47:      */
48:     function getSessionNode(date) {
49:         // Find/create table
50:         var tableId = ["hist", date.getDate(), date.getMonth(),
51:             date.getYear()].join("-");
52:         var table = document.getElementById(tableId);
53:         if (table === null) {
54:             table = document.createElement("table");
55:             table.id = tableId;
56: 
57:             // Caption contains human-readable date
58:             var caption = document.createElement("caption");
59:             caption.className = "date";
60:             var options = {
61:                 "weekday": "long",
62:                 "year": "numeric",
63:                 "month": "long",
64:                 "day": "numeric",
65:             };
66:             caption.innerHTML = date.toLocaleDateString("en-US", options);
67:             table.appendChild(caption);
68: 
69:             // Add table to page
70:             HIST_CONTAINER.appendChild(table);
71:         }
72: 
73:         // Find/create tbody
74:         var tbody = table.lastChild;
75:         if (tbody.tagName !== "TBODY") {
76:             tbody = document.createElement("tbody");
77:             table.appendChild(tbody);
78:         }
79: 
80:         // Create session-separator and new tbody if necessary
81:         if (tbody.lastChild !== null && lastItemDate !== null &&
82:                 window.SESSION_INTERVAL > 0) {
83:             var interval = lastItemDate.getTime() - date.getTime();
84:             if (interval > window.SESSION_INTERVAL) {
85:                 // Add session-separator
86:                 var sessionSeparator = document.createElement("td");
87:                 sessionSeparator.className = "session-separator";
88:                 sessionSeparator.colSpan = 2;
89:                 sessionSeparator.innerHTML = "&#167;";
90:                 table.appendChild(document.createElement("tr"));
91:                 table.lastChild.appendChild(sessionSeparator);
92: 
93:                 // Create new tbody
94:                 tbody = document.createElement("tbody");
95:                 table.appendChild(tbody);
96:             }
97:         }
