135:      * Get JSON from given URL.
136:      *
137:      * @param {string} url - the url to fetch data from.
138:      * @param {function} callback - the function to callback with data.
139:      * @returns {void}
140:      */
141:     function getJSON(url, callback) {
142:         var xhr = new XMLHttpRequest();
